const b = $input.first().json.body || $input.first().json;
function norm(p) {
  if (!p) return '';
  const s = String(p).trim();
  if (s.startsWith('+')) return '+' + s.replace(/\D/g, '');
  const d = s.replace(/\D/g, '');
  if (d.length === 9) return '+34' + d;
  return '+' + d;
}
const callSid = b.CallSid || '';
const telephone = norm(b.To);
const sd = $getWorkflowStaticData('global');
if (!sd.sofia_sessions) sd.sofia_sessions = {};
sd.sofia_sessions[callSid] = {
  etape: 'ouverture',
  telephone,
  duree_sec: 0,
  hors_sujet_count: 0,
  soft_limit: parseInt($env.AGENT_SOFT_LIMIT_SEC || '110', 10) || 110,
  data: {
    proprietaire: null, type_logement: null, code_postal: null, combles: null,
    acces_combles: null, calefaccion: null, creneau_rappel: null, nom_contact: null, telephone_final: null,
  },
  transcript_log: [],
  non_owner_count: 0,
  silence_count: 0,
};
const base = ($env.N8N_WEBHOOK_URL || '').replace(/\/$/, '');
const bucket = ($env.STORAGE_BUCKET_URL || '').replace(/\/$/, '');
const hook = bucket ? bucket + '/sofia_hook.mp3' : '';
const question = bucket ? bucket + '/sofia_question_propietario.mp3' : '';
const recTimeout = parseInt($env.SOFIA_RECORD_TIMEOUT || '5', 10) || 5;
const recMax = parseInt($env.SOFIA_RECORD_MAXLENGTH || '10', 10) || 10;
const pauseSec = parseInt($env.SOFIA_RECORD_PAUSE_SEC || '2', 10) || 2;
let twiml = '<?xml version="1.0" encoding="UTF-8"?><Response>';
if (hook && question) {
  twiml += '<Play>' + hook + '</Play>';
  twiml += '<Play>' + question + '</Play>';
} else if (bucket) {
  twiml += '<Play>' + bucket + '/sofia_ouverture.mp3</Play>';
}
twiml += '<Pause length="' + pauseSec + '"/>';
twiml += '<Record action="' + base + '/telephony/twilio/transcribe" maxLength="' + recMax + '" timeout="' + recTimeout + '" playBeep="false" trim="trim-silence"/>';
twiml += '</Response>';
return [{ json: { twiml, call_sid: callSid, telephone } }];

const b=$input.first().json.body||$input.first().json;
const ab=(b.AnsweredBy||'').toLowerCase();
const amd=['machine','fax'].some(x=>ab.includes(x))?(ab.includes('fax')?'fax':'machine'):'human';
const ev={event_type:'amd_result',call_sid:b.CallSid||'',from:'',to:'',recording_url:'',amd_result:amd,duration_sec:0,provider:'twilio',raw:b};
return [{json:ev}];

const b = $input.first().json.body || $input.first().json;
const dur = parseInt(b.RecordingDuration || 0, 10) || 0;
const ev = {
  event_type: dur > 25 ? 'call_ended' : 'recording_ready',
  call_sid: b.CallSid || '',
  from: b.From || '',
  to: b.To || '',
  recording_url: b.RecordingUrl || '',
  amd_result: 'unknown',
  duration_sec: dur,
  provider: 'twilio',
  raw: b,
};
return [{ json: ev }];

const b = $input.first().json.body || $input.first().json;
const recUrlRaw = b.RecordingUrl || '';
const recUrl = recUrlRaw && !recUrlRaw.endsWith('.mp3') ? recUrlRaw + '.mp3' : recUrlRaw;
const ev = {
  event_type: 'recording_ready',
  call_sid: b.CallSid || '',
  recording_url: recUrlRaw,
  duration_sec: parseInt(b.RecordingDuration || 0, 10) || 0,
  provider: 'twilio',
  to: b.To || '',
  from: b.From || '',
  raw: b,
};
const base = ($env.N8N_WEBHOOK_URL || '').replace(/\/$/, '');
const recTimeout = parseInt($env.SOFIA_RECORD_TIMEOUT || '5', 10) || 5;
const recMax = parseInt($env.SOFIA_RECORD_MAXLENGTH || '10', 10) || 10;
let recording_b64 = '';
const twSid = ($env.TWILIO_ACCOUNT_SID || '').trim();
const twToken = ($env.TWILIO_AUTH_TOKEN || '').trim();
const mp3Url = recUrl || (recUrlRaw ? (recUrlRaw.endsWith('.mp3') ? recUrlRaw : recUrlRaw + '.mp3') : '');
if (mp3Url && twSid && twToken) {
  try {
    const audioBuf = await this.helpers.httpRequest({
      method: 'GET',
      url: mp3Url,
      headers: {
        Authorization: 'Basic ' + Buffer.from(twSid + ':' + twToken).toString('base64'),
      },
      encoding: 'arraybuffer',
    });
    recording_b64 = Buffer.from(audioBuf).toString('base64');
  } catch (e) {
    recording_b64 = '';
  }
}
if (recording_b64) ev.recording_b64 = recording_b64;
const res = await this.helpers.httpRequest({
  method: 'POST',
  url: base + '/renov/conversation',
  body: ev,
  json: true,
  timeout: 30000,
});
const audio = res.audio_url || '';
const action = res.action || 'play_audio';
let twiml = '<?xml version="1.0" encoding="UTF-8"?><Response>';
if (audio) {
  twiml += '<Play>' + audio + '</Play>';
}
const pauseSec = parseInt($env.SOFIA_RECORD_PAUSE_SEC || '2', 10) || 2;
if (action === 'hangup' || res.qualified) {
  twiml += '<Hangup/>';
} else if (audio) {
  twiml += '<Pause length="' + pauseSec + '"/><Record action="' + base + '/telephony/twilio/transcribe" maxLength="' + recMax + '" timeout="' + recTimeout + '" playBeep="false" trim="trim-silence"/>';
} else {
  twiml += '<Hangup/>';
}
twiml += '</Response>';
return [{ json: { twiml, normalized: ev, engine: res } }];
